// DEV_RIO_603 Retention【LINE 継続営業・下書き準備】
// 既顧客への定期的な付加価値提供メッセージを LINE で準備。
const i = $input.first().json;
return [{ json: {
  customer_id: i.customer_id ?? 'cust-' + Math.random().toString(36).substr(2, 9),
  line_user_id: i.line_user_id ?? 'U' + Math.random().toString(36).substr(2, 9),
  customer_segment: i.customer_segment ?? 'general',
  months_as_customer: i.months_as_customer ?? 6,
  platform: 'line',
  action_type: 'send_retention_offer'
} }];

// 顧客セグメント別の継続営業メッセージを Claude 生成
const i = $input.first().json;
const segmentDesc = {
  general: '一般顧客',
  vip: 'VIP顧客',
  atrisk: 'リスク顧客（解約寸前）'
};
const prompt = `既顧客（セグメント: ${segmentDesc[i.customer_segment] || '不明'}、顧客期間: ${i.months_as_customer}ヶ月）への継続営業メッセージを作成してください。\n\n条件:\n- 100字以内、日本語\n- 付加価値提供に焦点（売上ではなく顧客の成功）\n- 長期的な関係構築を示唆\n- 出力は次のJSON配列のみ: [{"offer_type":"string","retention_message":"string"}]`;
const anthropic_body = {
  model: 'claude-haiku-4-5',
  max_tokens: 512,
  messages: [ { role: 'user', content: prompt } ]
};
return [{ json: { ...i, anthropic_body } }];

// Claude応答をパース。顧客セグメント別の継続営業下書き生成
const input = $input.first().json;
const ctx = $('Collect Customer Input').first().json;
let offers = [];
let parse_error = null;
if (input.error) {
  parse_error = 'anthropic_api_error: ' + JSON.stringify(input.error).slice(0, 300);
} else {
  try {
    const text = input.content && input.content[0] && input.content[0].text;
    if (!text) throw new Error('no text in response');
    const cleaned = text.trim().replace(/^```json\s*/i, '').replace(/```\s*$/, '');
    const match = cleaned.match(/\[[\s\S]*\]/);
    offers = JSON.parse(match ? match[0] : cleaned);
    if (!Array.isArray(offers) || offers.length === 0) throw new Error('offers missing/empty');
  } catch (e) {
    parse_error = 'parse_failed: ' + e.message;
  }
}
if (parse_error) offers = [{ offer_type: '手動作成', retention_message: '（AI応答の取得/解析に失敗。手動で継続営業オファーを作成してください）' }];
return [{ json: {
  customer_id: ctx.customer_id,
  line_user_id: ctx.line_user_id,
  customer_segment: ctx.customer_segment,
  retention_offers: offers,
  state: 'WAITING_APPROVAL',
  published: false,
  draft_error: parse_error,
  note: 'ドライラン。顧客継続営業下書きのみ。自動送信はしない。人間が確認して手動実行。'
} }];
